#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n);
    vector<int> cnt(101, 0);

    for (int& x : a) {
        cin >> x;
        ++cnt[x];
    }

    int D = 1;
    for (int i = 2; i <= 100; ++i) {
        if (cnt[i] > cnt[D]) D = i;
    }

    int tied = 0;
    for (int i = 1; i <= 100; ++i) {
        if (cnt[i] == cnt[D]) ++tied;
    }

    if (tied > 1) {
        cout << n;
        return 0;
    }

    const int offset = n;
    vector<int> first(2 * n + 1);
    vector<int> seen(2 * n + 1, 0);

    int answer = 0;
    int stamp = 0;

    for (int value = 1; value <= 100; ++value) {
        if (value == D) continue;

        ++stamp;
        int sum = 0;
        first[offset] = -1;
        seen[offset] = stamp;

        for (int j = 0; j < n; ++j) {
            if (a[j] == D) --sum;
            if (a[j] == value) ++sum;

            int index = sum + offset;
            if (seen[index] != stamp) {
                seen[index] = stamp;
                first[index] = j;
            } else {
                answer = max(answer, j - first[index]);
            }
        }
    }

    cout << answer;
    return 0;
}

